selector_to_html = {"a[href=\"#build-a-circuit\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Build a circuit<a class=\"headerlink\" href=\"#build-a-circuit\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_qubits</span></code> is the preferred public name for circuit size. Positional\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit(2)</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_wires=2</span></code>, and the legacy <code class=\"docutils literal notranslate\"><span class=\"pre\">nqubits=2</span></code> remain compatible, and\nconflicting aliases fail during construction. Internal IR, compiler, and runtime\nmappings continue to use <em>wire</em> for logical mappings.</p><p>Generated gate methods keep their concise positional form and also accept\nsemantic qubit keywords: <code class=\"docutils literal notranslate\"><span class=\"pre\">h(0)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">h(qubit=0)</span></code> are equivalent, <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(0,</span> <span class=\"pre\">1)</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">cx(control=0,</span> <span class=\"pre\">target=1)</span></code> are equivalent, symmetric two-qubit gates use\n<code class=\"docutils literal notranslate\"><span class=\"pre\">qubit1=</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit2=</span></code>, and the generic <code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit.gate(...)</span></code> keeps <code class=\"docutils literal notranslate\"><span class=\"pre\">wires=</span></code>.\nDuplicate, conflicting, or missing qubit arguments fail before an instruction is\nadded.</p>", "a[href=\"#read-the-result\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Read the result<a class=\"headerlink\" href=\"#read-the-result\" title=\"Link to this heading\">#</a></h2><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">result.measurement(index_or_name)</span></code> for a specific request and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">result.native()</span></code> only when intentionally depending on an unstable\nbackend-native object; backend attributes are not forwarded implicitly.</p>", "a[href=\"#plan-then-run\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Plan, then run<a class=\"headerlink\" href=\"#plan-then-run\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run(...)</span> <span class=\"pre\">-&gt;</span> <span class=\"pre\">fq.ExecutionResult</span></code> is the single recommended execution entry\npoint, and <code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit.run(...)</span></code> is equivalent to <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run(circuit,</span> <span class=\"pre\">...)</span></code>.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionOptions</span></code> owns backend-neutral configuration; measurement requests and\nan optional <code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.noise.NoiseModel</span></code> are semantic program inputs. Unknown\nkeyword arguments fail before planning.</p>", "a[href=\"#select-a-device-or-target\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Select a device or target<a class=\"headerlink\" href=\"#select-a-device-or-target\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionOptions.device</span></code> describes a device controlled by the current process,\nwhile <code class=\"docutils literal notranslate\"><span class=\"pre\">target</span></code> names an external execution destination:</p>", "a[href=\"#basic-usage\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Basic Usage<a class=\"headerlink\" href=\"#basic-usage\" title=\"Link to this heading\">#</a></h1><h2>Build a circuit<a class=\"headerlink\" href=\"#build-a-circuit\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_qubits</span></code> is the preferred public name for circuit size. Positional\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit(2)</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_wires=2</span></code>, and the legacy <code class=\"docutils literal notranslate\"><span class=\"pre\">nqubits=2</span></code> remain compatible, and\nconflicting aliases fail during construction. Internal IR, compiler, and runtime\nmappings continue to use <em>wire</em> for logical mappings.</p><p>Generated gate methods keep their concise positional form and also accept\nsemantic qubit keywords: <code class=\"docutils literal notranslate\"><span class=\"pre\">h(0)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">h(qubit=0)</span></code> are equivalent, <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(0,</span> <span class=\"pre\">1)</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">cx(control=0,</span> <span class=\"pre\">target=1)</span></code> are equivalent, symmetric two-qubit gates use\n<code class=\"docutils literal notranslate\"><span class=\"pre\">qubit1=</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit2=</span></code>, and the generic <code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit.gate(...)</span></code> keeps <code class=\"docutils literal notranslate\"><span class=\"pre\">wires=</span></code>.\nDuplicate, conflicting, or missing qubit arguments fail before an instruction is\nadded.</p>", "a[href=\"#reproducible-plans\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Reproducible plans<a class=\"headerlink\" href=\"#reproducible-plans\" title=\"Link to this heading\">#</a></h2><p>Pass a plan straight to <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code> for an inspectable, reproducible execution: the\nsupplied plan is validated and executed without replanning or recompiling, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">result.plan</span> <span class=\"pre\">is</span> <span class=\"pre\">plan</span></code> holds in the same process. Plan identity covers the\ncanonical IR, resolved execution semantics, compiler pipeline, required\nenvironment, and the selected decision, and a JSON round trip verifies every\nfingerprint before execution:</p>", "a[href=\"#advanced-interfaces\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Advanced interfaces<a class=\"headerlink\" href=\"#advanced-interfaces\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.runtime.run_native</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.simulation.mps.run_mps</span></code>, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.simulation.tensor_network.run_tensor_network</span></code> exist for callers that\nexplicitly need native backend result objects or backend-specific controls.\nPrefer <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code> unless one of those is required.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
